alter table public.matches
  add column if not exists legacy_source_key text,
  add column if not exists legacy_rules boolean not null default false,
  add column if not exists elo_locked boolean not null default false;

alter table public.matches
  drop constraint if exists matches_red_score_check,
  drop constraint if exists matches_blue_score_check,
  drop constraint if exists matches_scores_nonnegative,
  drop constraint if exists valid_final_score;

alter table public.matches
  add constraint matches_scores_nonnegative check (
    red_score between 0 and 99 and blue_score between 0 and 99
  ),
  add constraint valid_final_score check (
    (
      not legacy_rules
      and (
        (red_score = 6 and blue_score between 0 and 5)
        or (blue_score = 6 and red_score between 0 and 5)
      )
    )
    or (
      legacy_rules
      and red_score <> blue_score
      and greatest(red_score, blue_score) >= 6
    )
  );

create unique index if not exists matches_legacy_source_key_unique
  on public.matches (legacy_source_key)
  where legacy_source_key is not null;

create or replace function public.recalculate_elo()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_match record;
  v_red_players uuid[];
  v_blue_players uuid[];
  v_red_rating numeric;
  v_blue_rating numeric;
  v_expected_red numeric;
  v_red_delta numeric;
begin
  update public.players set current_elo = 1000;

  for current_match in
    select * from public.matches order by played_at, created_at, id
  loop
    select array_agg(player_id) into v_red_players
    from public.match_players
    where match_id = current_match.id and team = 'red';

    select array_agg(player_id) into v_blue_players
    from public.match_players
    where match_id = current_match.id and team = 'blue';

    if current_match.elo_locked then
      update public.match_players mp
      set elo_before = p.current_elo
      from public.players p
      where mp.match_id = current_match.id and p.id = mp.player_id;

      update public.players p
      set current_elo = round(p.current_elo + mp.elo_delta, 2)
      from public.match_players mp
      where mp.match_id = current_match.id and mp.player_id = p.id;
      continue;
    end if;

    select avg(current_elo) into v_red_rating
    from public.players where id = any(v_red_players);
    select avg(current_elo) into v_blue_rating
    from public.players where id = any(v_blue_players);

    v_expected_red := 1 / (1 + power(10, (v_blue_rating - v_red_rating) / 400));
    v_red_delta := round((
      32 * ((case when current_match.red_score > current_match.blue_score then 1 else 0 end) - v_expected_red)
    )::numeric, 2);

    update public.match_players mp
    set elo_before = p.current_elo,
        elo_delta = case when mp.team = 'red' then v_red_delta else -v_red_delta end
    from public.players p
    where mp.match_id = current_match.id and p.id = mp.player_id;

    update public.players
    set current_elo = round(
      current_elo + case when id = any(v_red_players) then v_red_delta else -v_red_delta end,
      2
    )
    where id = any(v_red_players || v_blue_players);
  end loop;

  update public.players set updated_at = now();
end;
$$;

create or replace function public.update_match(
  p_match_id uuid,
  p_red_score smallint,
  p_blue_score smallint,
  p_played_at timestamptz
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_approved() then
    raise exception 'Account non approvato';
  end if;

  if not (
    (p_red_score = 6 and p_blue_score between 0 and 5)
    or (p_blue_score = 6 and p_red_score between 0 and 5)
  ) then
    raise exception 'La partita termina a sei goal, senza scarto';
  end if;

  update public.matches
  set red_score = p_red_score,
      blue_score = p_blue_score,
      played_at = p_played_at,
      edited_at = now(),
      edited_by = auth.uid(),
      legacy_rules = false,
      elo_locked = false
  where id = p_match_id;

  if not found then
    raise exception 'Partita non trovata';
  end if;

  perform public.recalculate_elo();
end;
$$;

