      source_key text,
      source_order integer,
      played_at timestamptz,
      blue_players text[],
      red_players text[],
      blue_score smallint,
      red_score smallint,
      blue_elo numeric,
      red_elo numeric
    )
    order by played_at, source_order desc
  loop
    if exists (
      select 1 from public.matches where legacy_source_key = v_match.source_key
    ) then
      continue;
    end if;

    if cardinality(v_match.blue_players) <> 2
      or cardinality(v_match.red_players) <> 2
      or v_match.blue_elo <> -v_match.red_elo then
      raise exception 'Partita legacy non valida: %', v_match.source_key;
    end if;

    v_match_id := gen_random_uuid();
    insert into public.matches (
      id,
      played_at,
      red_score,
      blue_score,
      created_at,
      created_by,
      legacy_source_key,
      legacy_rules,
      elo_locked
    ) values (
      v_match_id,
      v_match.played_at,
      v_match.red_score,
      v_match.blue_score,
      v_match.played_at,
      v_created_by,
      v_match.source_key,
      true,
      true
    );

    insert into public.match_players (
      match_id,
      player_id,
      team,
      elo_before,
      elo_delta
    )
    select
      v_match_id,
      player.id,
      'blue'::public.team_color,
      player.current_elo,
      v_match.blue_elo
    from public.players player
    join unnest(v_match.blue_players) imported_name(name)
      on lower(trim(player.name)) = lower(trim(imported_name.name))
    union all
    select
      v_match_id,
      player.id,
      'red'::public.team_color,
      player.current_elo,
      v_match.red_elo
    from public.players player
    join unnest(v_match.red_players) imported_name(name)
      on lower(trim(player.name)) = lower(trim(imported_name.name));

    get diagnostics v_participant_count = row_count;
    if v_participant_count <> 4 then
      raise exception 'Giocatori incompleti per %', v_match.source_key;
    end if;

    update public.players
    set current_elo = round(current_elo + v_match.blue_elo, 2),
        updated_at = now()
    where lower(trim(name)) in (
      select lower(trim(imported_name.name))
      from unnest(v_match.blue_players) imported_name(name)
    );

    update public.players
    set current_elo = round(current_elo + v_match.red_elo, 2),
        updated_at = now()
    where lower(trim(name)) in (
      select lower(trim(imported_name.name))
      from unnest(v_match.red_players) imported_name(name)
    );
  end loop;
end;
$$;
